1	//! Validated Qwen3.5 model config.
2	//!
3	//! This module owns the *model* geometry: deserialized-from-disk [`RawConfig`]
4	//! is converted once into a validated [`Config35`] via [`TryFrom`]. It has no
5	//! knowledge of tensor parallelism — sharded/local dimensions, shard ranges and
6	//! the TP assignment live in [`super::tp`] as a separate directional boundary.
7	
8	use std::fs;
9	
10	use anyhow::Result;
11	use serde::Deserialize;
12	
13	use super::error::ConfigError;
14	
15	/// Which attention variant a layer uses. Model-level (TP-agnostic) layout.
16	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
17	pub(crate) enum LayerType {
18	    FullAttention,
19	    LinearAttention,
20	}
21	
22	/// RoPE block inside `text_config`. Only these two keys are read.
23	#[derive(Debug, Deserialize)]
24	struct RopeParameters {
25	    rope_theta: f64,
26	    partial_rotary_factor: f64,
27	}
28	
29	/// Raw `text_config` block, exactly as it appears on disk.
30	#[derive(Debug, Deserialize)]
31	pub(crate) struct TextConfig {
32	    hidden_size: usize,
33	    intermediate_size: usize,
34	    num_hidden_layers: usize,
35	    num_attention_heads: usize,
36	    num_key_value_heads: usize,
37	    head_dim: usize,
38	    vocab_size: usize,
39	    rms_norm_eps: f64,
40	    layer_types: Vec<String>,
41	    linear_conv_kernel_dim: usize,
42	    linear_key_head_dim: usize,
43	    linear_num_key_heads: usize,
44	    linear_num_value_heads: usize,
45	    linear_value_head_dim: usize,
46	    rope_parameters: RopeParameters,
47	    max_position_embeddings: Option<usize>,
48	    tie_word_embeddings: Option<bool>,
49	    eos_token_id: u32,
50	}
51	
52	/// Raw Qwen3.5 config as deserialized from `config.json`. Held only long enough
53	/// to be validated into a [`Config35`].
54	#[derive(Debug, Deserialize)]
55	pub(crate) struct RawConfig {
56	    text_config: TextConfig,
57	    max_position_embeddings: Option<usize>,
58	    tie_word_embeddings: Option<bool>,
59	}
60	
61	/// Head dims baked into the kernels; head counts are runtime parameters.
62	pub(crate) const GDN_AOT_KEY_HEAD_DIM: usize = 128;
63	pub(crate) const GDN_AOT_VALUE_HEAD_DIM: usize = 128;
64	pub(crate) const LINEAR_CONV_MAX_KERNEL_DIM: usize = 4;
65	const FULL_ATTN_HEAD_DIM: usize = 256;
66	
67	/// Validated Qwen3.5 model configuration (text-only).
68	///
69	/// Every cross-field and kernel-AOT rule is enforced here, at the single
70	/// [`Self::try_from`]/[`Self::from_file`] boundary, so downstream code can only
71	/// observe a model that is known to be loadable. Tensor-parallel sharding is
72	/// never a property of this type.
73	#[derive(Debug)]
74	pub(crate) struct Config35 {
75	    // Common
76	    pub(crate) hidden_size: usize,
77	    pub(crate) intermediate_size: usize,
78	    pub(crate) num_hidden_layers: usize,
79	    pub(crate) vocab_size: usize,
80	    pub(crate) rms_norm_eps: f32,
81	    pub(crate) eos_token_id: u32,
82	
83	    // Full attention params
84	    pub(crate) num_attention_heads: usize,
85	    pub(crate) num_key_value_heads: usize,
86	    pub(crate) head_dim: usize,
87	
88	    // Linear attention params
89	    pub(crate) linear_num_key_heads: usize,
90	    pub(crate) linear_key_head_dim: usize,
91	    pub(crate) linear_num_value_heads: usize,
92	    pub(crate) linear_value_head_dim: usize,
93	    pub(crate) linear_conv_kernel_dim: usize,
94	
95	    // RoPE
96	    pub(crate) rope_theta: f32,
97	    pub(crate) rotary_dim: usize,
98	    pub(crate) max_position_embeddings: usize,
99	
100	    // Layer layout
101	    pub(crate) layer_types: Vec<LayerType>,
102	
103	    /// `false` requires a top-level `lm_head.weight`; `true` reuses `embed_tokens`.
104	    pub(crate) tie_word_embeddings: bool,
105	
106	    /// Token-selection width: `vocab_size` bounded to the frontend-decodable
107	    /// vocab, then rounded up to the logits GEMM's tile multiple. Buffers and
108	    /// the sampler arena span this width.
109	    pub(crate) selection_vocab: usize,
110	    /// Tokenizer-decodable width: the rows past it are suppressed to -inf and
111	    /// are what the argmax-vs-sample routing is measured against.
112	    pub(crate) decodable_vocab: usize,
113	}
114	
115	impl Config35 {
116	    /// Load and validate `config.json` from a model directory.
117	    pub(crate) fn from_file(model_path: &str) -> Result<Self> {
118	        let config_path = format!("{}/config.json", model_path);
119	        let content = fs::read_to_string(&config_path)?;
120	        let raw: RawConfig = serde_json::from_str(&content)?;
121	        let config = Self::try_from(raw)?;
122	        Ok(config)
123	    }
124	
125	    /// Number of full attention layers in the model.
126	    pub(crate) fn num_full_attention_layers(&self) -> usize {
127	        self.layer_types
128	            .iter()
129	            .filter(|&&t| t == LayerType::FullAttention)
130	            .count()
131	    }
132	
133	    /// Q dimension for full attention (without gate).
134	    pub(crate) fn full_attn_q_dim(&self) -> usize {
135	        self.num_attention_heads * self.head_dim
136	    }
137	
138	    /// KV dimension for full attention.
139	    pub(crate) fn full_attn_kv_dim(&self) -> usize {
140	        self.num_key_value_heads * self.head_dim
141	    }
142	
143	    pub(crate) fn decode_group_is_compiled(&self) -> bool {
144	        // Uncompiled GQA groups use the batched hybrid eager fallback.
145	        pegainfer_core::ops::SUPPORTED_GQA_GROUP_SIZES
146	            .contains(&(self.num_attention_heads / self.num_key_value_heads))
147	    }
148	
149	    /// Z projection output dimension for linear attention.
150	    pub(crate) fn linear_attn_z_dim(&self) -> usize {
151	        self.linear_num_value_heads * self.linear_value_head_dim
152	    }
153	
154	    /// Bound the output-selection width to the frontend-decodable vocab, which
155	    /// also records the semantic width the argmax-vs-sample routing uses.
156	    ///
157	    /// The frontend decodes a dense prefix of the vocab; the checkpoint may pad
158	    /// beyond it. Refusing a tokenizer wider than the checkpoint is the
159	    /// fail-closed rule, and it is checked here at the validation boundary
160	    /// rather than scattered through the loader.
161	    pub(crate) fn bound_selection_vocab(
162	        &mut self,
163	        effective_vocab: usize,
164	    ) -> Result<(), ConfigError> {
165	        if effective_vocab > self.vocab_size {
166	            return Err(ConfigError::EffectiveVocabExceedsCheckpoint {
167	                used: effective_vocab,
168	                vocab_size: self.vocab_size,
169	            });
170	        }
171	        // The logits GEMM's M dimension and the output matrix's leading
172	        // dimension both take this width; an unaligned value (Qwen3.5-4B's
173	        // tokenizer decodes 248077) forces cublasLt onto an align-1 sm_75-era
174	        // kernel that costs ~1.7 ms/decode-step on sm_80. Round the GEMM width
175	        // up to the tile-aligned multiple — the checkpoint's remaining rows are
176	        // real trained embeddings and stay inside the mapped weight.
177	        let aligned = effective_vocab.next_multiple_of(128);
178	        self.decodable_vocab = effective_vocab;
179	        self.selection_vocab = aligned.min(self.vocab_size);
180	        Ok(())
181	    }
182	}
183	
184	/// Validate a raw Qwen3.5 config into a [`Config35`].
185	///
186	/// Every check here is a static, load-time invariant: an invalid model file is
187	/// rejected before any weight is mapped or any CUDA buffer is allocated. The
188	/// kernel head dims are compile-time AOT constants, so a config that disagrees
189	/// cannot be served and is rejected here rather than at first kernel launch.
190	impl TryFrom<RawConfig> for Config35 {
191	    type Error = ConfigError;
192	
193	    fn try_from(raw: RawConfig) -> std::result::Result<Self, Self::Error> {
194	        let root_max_position_embeddings = raw.max_position_embeddings;
195	        let root_tie_word_embeddings = raw.tie_word_embeddings;
196	        let t = raw.text_config;
197	
198	        let tie_word_embeddings = t
199	            .tie_word_embeddings
200	            .or(root_tie_word_embeddings)
201	            .ok_or(ConfigError::MissingTieWordEmbeddings)?;
202	
203	        let layer_types: Vec<LayerType> = t
204	            .layer_types
205	            .iter()
206	            .map(|s| match s.as_str() {
207	                "full_attention" => Ok(LayerType::FullAttention),
208	                "linear_attention" => Ok(LayerType::LinearAttention),
209	                other => Err(ConfigError::UnknownLayerType(other.to_string())),
210	            })
211	            .collect::<std::result::Result<_, _>>()?;
212	
213	        if layer_types.len() != t.num_hidden_layers {
214	            return Err(ConfigError::LayerTypeCountMismatch {
215	                actual: layer_types.len(),
216	                expected: t.num_hidden_layers,
217	            });
218	        }
219	
220	        let rotary_dim = (t.head_dim as f64 * t.rope_parameters.partial_rotary_factor) as usize;
221	        if rotary_dim == 0 {
222	            return Err(ConfigError::ZeroRotaryDim);
223	        }
224	
225	        let max_position_embeddings = t
226	            .max_position_embeddings
227	            .or(root_max_position_embeddings)
228	            .ok_or(ConfigError::MissingMaxPositionEmbeddings)?;
229	        if max_position_embeddings == 0 {
230	            return Err(ConfigError::NonPositiveMaxPositionEmbeddings);
231	        }
232	
233	        if t.linear_key_head_dim != GDN_AOT_KEY_HEAD_DIM
234	            || t.linear_value_head_dim != GDN_AOT_VALUE_HEAD_DIM
235	        {
236	            return Err(ConfigError::GdnAotHeadDimMismatch {
237	                key: t.linear_key_head_dim,
238	                value: t.linear_value_head_dim,
239	                expected_key: GDN_AOT_KEY_HEAD_DIM,
240	                expected_value: GDN_AOT_VALUE_HEAD_DIM,
241	            });
242	        }
243	        if t.head_dim != FULL_ATTN_HEAD_DIM {
244	            return Err(ConfigError::FullAttnHeadDimMismatch {
245	                expected: FULL_ATTN_HEAD_DIM,
246	                actual: t.head_dim,
247	            });
248	        }
249	        if !(1..=LINEAR_CONV_MAX_KERNEL_DIM).contains(&t.linear_conv_kernel_dim) {
250	            return Err(ConfigError::LinearConvKernelDim {
251	                max: LINEAR_CONV_MAX_KERNEL_DIM,
252	                actual: t.linear_conv_kernel_dim,
253	            });
254	        }
255	        if t.linear_num_key_heads == 0
256	            || !t
257	                .linear_num_value_heads
258	                .is_multiple_of(t.linear_num_key_heads)
259	        {
260	            return Err(ConfigError::LinearHeadDivisibility {
261	                key_heads: t.linear_num_key_heads,
262	                value_heads: t.linear_num_value_heads,
263	            });
264	        }
265	        if t.num_key_value_heads == 0
266	            || !t.num_attention_heads.is_multiple_of(t.num_key_value_heads)
267	        {
268	            return Err(ConfigError::AttentionHeadDivisibility {
269	                attention_heads: t.num_attention_heads,
270	                key_value_heads: t.num_key_value_heads,
271	            });
272	        }
273	
274	        Ok(Self {
275	            hidden_size: t.hidden_size,
276	            intermediate_size: t.intermediate_size,
277	            num_hidden_layers: t.num_hidden_layers,
278	            vocab_size: t.vocab_size,
279	            rms_norm_eps: t.rms_norm_eps as f32,
280	            eos_token_id: t.eos_token_id,
281	            num_attention_heads: t.num_attention_heads,
282	            num_key_value_heads: t.num_key_value_heads,
283	            head_dim: t.head_dim,
284	            linear_num_key_heads: t.linear_num_key_heads,
285	            linear_key_head_dim: t.linear_key_head_dim,
286	            linear_num_value_heads: t.linear_num_value_heads,
287	            linear_value_head_dim: t.linear_value_head_dim,
288	            linear_conv_kernel_dim: t.linear_conv_kernel_dim,
289	            rope_theta: t.rope_parameters.rope_theta as f32,
290	            rotary_dim,
291	            max_position_embeddings,
292	            layer_types,
293	            tie_word_embeddings,
294	            selection_vocab: t.vocab_size,
295	            decodable_vocab: t.vocab_size,
296	        })
297	    }
298	}
299	
300	#[cfg(test)]
301	mod tests {
302	    use super::*;
303	
304	    const VALID_RAW: &str = r#"{
305	  "max_position_embeddings": 4096,
306	  "tie_word_embeddings": true,
307	  "text_config": {
308	    "hidden_size": 512,
309	    "intermediate_size": 1024,
310	    "num_hidden_layers": 2,
311	    "num_attention_heads": 4,
312	    "num_key_value_heads": 2,
313	    "head_dim": 256,
314	    "vocab_size": 1000,
315	    "rms_norm_eps": 1e-6,
316	    "layer_types": ["linear_attention", "full_attention"],
317	    "linear_conv_kernel_dim": 4,
318	    "linear_key_head_dim": 128,
319	    "linear_num_key_heads": 16,
320	    "linear_num_value_heads": 48,
321	    "linear_value_head_dim": 128,
322	    "rope_parameters": { "rope_theta": 10000.0, "partial_rotary_factor": 0.25 },
323	    "eos_token_id": 0
324	  }
325	}"#;
326	
327	    fn parse(raw: &str) -> RawConfig {
328	        serde_json::from_str(raw).expect("fixture must deserialize")
329	    }
330	
331	    fn config(raw: &str) -> Config35 {
332	        Config35::try_from(parse(raw)).expect("fixture must validate")
333	    }
334	
335	    #[test]
336	    fn valid_fixture_loads() {
337	        let config = config(VALID_RAW);
338	        assert_eq!(config.num_full_attention_layers(), 1);
339	        assert_eq!(config.vocab_size, 1000);
340	    }
341	
342	    #[test]
343	    fn selection_vocab_bound_aligns_to_tile_multiple() {
344	        let mut config = config(VALID_RAW);
345	        config
346	            .bound_selection_vocab(977)
347	            .expect("977 decodes within vocab 1000");
348	        // 977 -> next 128 multiple (1024) clamped to the checkpoint's rows.
349	        assert_eq!(config.selection_vocab, 1000);
350	        assert_eq!(config.decodable_vocab, 977);
351	
352	        config
353	            .bound_selection_vocab(769)
354	            .expect("769 decodes within vocab 1000");
355	        // 769 -> 896: aligned, below the checkpoint rows, so the pad region is
356	        // 769..896.
357	        assert_eq!(config.selection_vocab, 896);
358	        assert_eq!(config.decodable_vocab, 769);
359	    }
360	
361	    #[test]
362	    fn selection_vocab_bound_still_rejects_wider_tokenizers() {
363	        let mut config = config(VALID_RAW);
364	        let err = config
365	            .bound_selection_vocab(1001)
366	            .expect_err("a tokenizer wider than the checkpoint is rejected");
367	        assert!(matches!(
368	            err,
369	            ConfigError::EffectiveVocabExceedsCheckpoint { .. }
370	        ));
371	    }
372	
373	    #[test]
374	    fn missing_tie_word_embeddings_is_typed() {
375	        let json = VALID_RAW.replace("\"tie_word_embeddings\": true,", "");
376	        let err = Config35::try_from(parse(&json)).unwrap_err();
377	        assert_eq!(err, ConfigError::MissingTieWordEmbeddings);
378	    }
379	
380	    #[test]
381	    fn unknown_layer_type_is_typed() {
382	        let json = VALID_RAW.replace("linear_attention", "window_attention");
383	        let err = Config35::try_from(parse(&json)).unwrap_err();
384	        assert_eq!(
385	            err,
386	            ConfigError::UnknownLayerType("window_attention".to_string())
387	        );
388	    }
389	
390	    #[test]
391	    fn layer_type_count_mismatch_is_typed() {
392	        let json = VALID_RAW.replace(
393	            "[\"linear_attention\", \"full_attention\"]",
394	            "[\"linear_attention\"]",
395	        );
396	        let err = Config35::try_from(parse(&json)).unwrap_err();
397	        assert_eq!(
398	            err,
399	            ConfigError::LayerTypeCountMismatch {
400	                actual: 1,
401	                expected: 2,
402	            }
403	        );
404	    }
405	
406	    #[test]
407	    fn missing_max_position_embeddings_is_typed() {
408	        let json = VALID_RAW.replace("\"max_position_embeddings\": 4096,", "");
409	        let err = Config35::try_from(parse(&json)).unwrap_err();
410	        assert_eq!(err, ConfigError::MissingMaxPositionEmbeddings);
411	    }
412	
413	    #[test]
414	    fn wide_linear_conv_kernel_is_typed() {
415	        let json = VALID_RAW.replace(
416	            "\"linear_conv_kernel_dim\": 4",
417	            "\"linear_conv_kernel_dim\": 5",
418	        );
419	        let err = Config35::try_from(parse(&json)).unwrap_err();
420	        assert_eq!(
421	            err,
422	            ConfigError::LinearConvKernelDim {
423	                max: LINEAR_CONV_MAX_KERNEL_DIM,
424	                actual: 5,
425	            }
426	        );
427	    }
428	
429	    #[test]
430	    fn acceptance_of_48_value_heads() {
431	        // Regression guard: 48 value heads with 16 key heads must load.
432	        config(VALID_RAW);
433	    }
434	}
